import React, { useEffect, useState } from "react";
import axios from "axios";
import ListingCard from "./ListingCard";
import { useNavigate } from "react-router-dom";

export default function CustomerDashboard() {
  const [listings, setListings] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();

  // Check user role and redirect if seller
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login"); // redirect to login if not logged in
      return;
    }
    try {
      const decoded = JSON.parse(atob(token.split(".")[1]));
      if (decoded.role === "seller") {
        navigate("/seller-dashboard"); // redirect sellers
      }
    } catch (err) {
      console.error("Invalid token:", err);
      navigate("/login");
    }
  }, [navigate]);

  // Fetch all listings (visible to customers)
  useEffect(() => {
    const fetchListings = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/listings/all"); // endpoint for all listings
        console.log("API Response:", res.data); // debug
        setListings(res.data);
        setFiltered(res.data);
      } catch (err) {
        console.error("Error fetching listings:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchListings();
  }, []);

  // Debounced search/filter
  useEffect(() => {
    const delayFilter = setTimeout(() => {
      const q = search.toLowerCase();
      const result = listings.filter(
        (listing) =>
          listing.title?.toLowerCase().includes(q) ||
          listing.description?.toLowerCase().includes(q) ||
          listing.location?.toLowerCase().includes(q) ||
          listing.propertyType?.toLowerCase().includes(q) ||
          String(listing.price)?.includes(q)
      );
      setFiltered(result);
    }, 200);

    return () => clearTimeout(delayFilter);
  }, [search, listings]);

  return (
    <div style={{ padding: "40px 20px" }}>
      <h2 style={{ textAlign: "center", marginBottom: "20px" }}>
        Available Homes, Rooms & Offices
      </h2>

      <div style={{ textAlign: "center", marginBottom: "30px" }}>
        <input
          type="text"
          placeholder="Search by home, rent, office, hotel..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{
            padding: "12px 16px",
            width: "65%",
            maxWidth: "550px",
            borderRadius: "10px",
            border: "1px solid #888",
            fontSize: "16px",
            outline: "none",
          }}
        />
      </div>

      {loading ? (
        <p style={{ textAlign: "center" }}>Loading listings...</p>
      ) : filtered.length === 0 ? (
        <p style={{ textAlign: "center" }}>No listings found.</p>
      ) : (
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
            gap: "20px",
            justifyItems: "center",
          }}
        >
          {filtered.map((listing) => (
            <ListingCard key={listing._id} listing={listing} />
          ))}
        </div>
      )}
    </div>
  );
}
